const ADVENTURE_CHAPTER_19_1={"id":"chapter19_1","number":"19.1","levelRange":"55–57","mapBackground":"assets/story/map_hallvalla_chapter_2_1.webp","title":"Las siete cerraduras","desc":"Bajo HallValla existen siete cerraduras que no corresponden a las siete llaves: son defensas independientes construidas para detener a quien consiga reunirlas.","introTitle":"19.1 Las siete cerraduras","introText":"La placa de Subotai abre una sala circular con siete puertas. El diseño confirma algo que tu padre entendió demasiado tarde: las llaves nunca fueron suficientes. Los fundadores construyeron una segunda defensa destinada precisamente a detener a un portador de las siete. Satanyahu ha copiado las marcas, pero no ha superado estas pruebas. Por primera vez desde que empezó la persecución, puedes alcanzarlo antes de que complete el siguiente paso.","requiresChapter":"chapter18_1","packType":"improved_magic_trap","battles":[{"id":"chapter19_1_battle1","num":1,"title":"La cerradura del valor","enemyName":"Guerrero de la Primera Cerradura","enemyLeaderType":"warrior","image":"assets/story/adventure_1_1/1_1_5_el_usurpador.webp","enemyIntro":"La primera cerradura responde a una formación que no retrocede ante una fuerza superior.","xp":2400,"gold":684,"cardPack":true,"packType":"improved_magic_trap","enemyLegendaryCards":["leonidas","julius_caesar","hector_troy","richard_lionheart","alexander_magnus"],"adaptiveFixedDeck":[["leonidas",1],["julius_caesar",1],["hector_troy",1],["richard_lionheart",1],["alexander_magnus",1],["roman_legionary",3],["greek_hoplite",3],["guardian",3],["armored_man_at_arms",3],["samurai_katana",3],["spearman",3],["dust_guard_plus",2],["shield_wall",2],["heal",2],["pharaoh_blessing_plus",1]],"adaptiveCoreMin":{"leonidas":1,"julius_caesar":1,"roman_legionary":2,"greek_hoplite":2,"guardian":2},"adaptiveMaxSwaps":10,"aiLevel":55,"aiDrawBonus":8,"aiHonorBonus":22,"aiStyle":"Tier 5 · Mapa 19 · warrior adaptativo de alta dificultad","desc":"Supera la prueba de valor sin sacrificar tus unidades por orgullo."},{"id":"chapter19_1_battle2","num":2,"title":"La cerradura de la distancia","enemyName":"Arquera de la Segunda Cerradura","enemyLeaderType":"archer","image":"assets/story/adventure_2_1/2_1_3_el_blanco_de_invierno.webp","enemyIntro":"La segunda prueba castiga a quien avance sin leer el terreno. Cada plataforma revela otra línea de tiro.","xp":2435,"gold":693,"cardPack":true,"packType":"improved_magic_trap","enemyLegendaryCards":["arjuna","simo_hayha","nasu_no_yoichi"],"adaptiveFixedDeck":[["arjuna",1],["simo_hayha",1],["nasu_no_yoichi",1],["archer",3],["egyptian_line_archer",3],["new_kingdom_archer",3],["roman_auxiliary_sagittarius",3],["samurai_yabusame",3],["scythian_horse_archer",3],["fireball",2],["poison_spell",2],["paralysis_spell",2],["skirmisher_cloak",1],["retreat_strap",1],["warning_rune_plus",1]],"adaptiveCoreMin":{"arjuna":1,"simo_hayha":1,"archer":2,"new_kingdom_archer":2,"roman_auxiliary_sagittarius":2},"adaptiveMaxSwaps":10,"aiLevel":55,"aiDrawBonus":8,"aiHonorBonus":22,"aiStyle":"Tier 5 · Mapa 19 · archer adaptativo de alta dificultad","desc":"Cruza la prueba de distancia manteniendo el control del campo."},{"id":"chapter19_1_battle3","num":3,"title":"La cerradura del silencio","enemyName":"Sombra de la Tercera Cerradura","enemyLeaderType":"assassin","image":"assets/story/adventure_3_1/3_1_3_el_maestro_sin_espada.webp","enemyIntro":"La tercera puerta borra nombres y señales. Solo quedan decisiones tomadas sin información completa.","xp":2470,"gold":702,"cardPack":true,"packType":"improved_magic_trap","enemyLegendaryCards":["hattori_hanzo","fuma_kotaro","miyamoto_musashi"],"adaptiveFixedDeck":[["hattori_hanzo",1],["fuma_kotaro",1],["miyamoto_musashi",1],["geisha_encubierta",3],["scout",3],["saboteador_iga",3],["samurai_katana",3],["ulfhednar",3],["shadow_cut",2],["false_crown",2],["broken_blood_oath",2],["poison_spell",2],["paralysis_spell",2],["smoke_bomb",2]],"adaptiveCoreMin":{"hattori_hanzo":1,"fuma_kotaro":1,"geisha_encubierta":2,"scout":2,"saboteador_iga":2},"adaptiveMaxSwaps":10,"aiLevel":56,"aiDrawBonus":8,"aiHonorBonus":23,"aiStyle":"Tier 5 · Mapa 19 · assassin adaptativo de alta dificultad","desc":"Encuentra la salida sin depender de las marcas de Satanyahu."},{"id":"chapter19_1_battle4","num":4,"title":"La cerradura de la memoria","enemyName":"Hechicero de la Sexta Cerradura","enemyLeaderType":"mage","image":"assets/story/adventure_6_1/6_1_5_la_corona_de_ceniza.webp","enemyIntro":"Las cerraduras cuarta, quinta y sexta convergen en una cámara que reproduce tus recuerdos de Terral y de tu padre. La prueba intenta detectar si la venganza puede todavía dirigir tus decisiones.","xp":2505,"gold":711,"cardPack":true,"packType":"improved_magic_trap","enemyLegendaryCards":["king_solomon","merlin","morgana","ericto"],"adaptiveFixedDeck":[["king_solomon",1],["merlin",1],["morgana",1],["ericto",1],["arcane_adept",3],["acolyte_healer",3],["saboteador_iga",3],["guardian",3],["samurai_katana",3],["fireball",3],["sand_curse_plus",2],["poison_spell",2],["paralysis_spell",2],["heal",1],["stabilizing_focus",1]],"adaptiveCoreMin":{"king_solomon":1,"merlin":1,"arcane_adept":2,"acolyte_healer":2,"saboteador_iga":2},"adaptiveMaxSwaps":10,"aiLevel":56,"aiDrawBonus":8,"aiHonorBonus":23,"aiStyle":"Tier 5 · Mapa 19 · mage adaptativo de alta dificultad","desc":"Conserva tus recuerdos sin permitir que decidan por ti."},{"id":"chapter19_1_battle5","num":5,"title":"La bestia de la séptima cerradura","enemyName":"Beowulf","enemyLeaderType":"axe","image":"assets/story/adventure_4_1/4_1_4_el_estratega_errante.webp","enemyIntro":"Beowulf custodia la última cerradura frente a una puerta ya dañada desde el otro lado. Satanyahu está cerca. El guardián solo permitirá continuar a quien pueda vencerlo sin usar el eco de las siete llaves como atajo. Cuando cae, abre la cerradura y se une a la persecución. Detrás de la puerta escuchas la voz de Satanyahu sin magia ni distancia. Está en la siguiente cámara.","xp":2540,"gold":720,"cardPack":false,"packType":"improved_magic_trap","enemyLegendaryCards":["beowulf","ragnar_lodbrok","lu_bu","spartacus","cu_chulainn"],"adaptiveFixedDeck":[["beowulf",1],["ragnar_lodbrok",1],["lu_bu",1],["spartacus",1],["cu_chulainn",1],["berserker",3],["berserker_de_oso",3],["ulfhednar",3],["huscarl_anglosajon_hacha",3],["guardia_varega_hacha",3],["tanned_hide_harness",2],["rupture_bracers",2],["war_visor",2],["heal",2],["dust_guard_plus",1],["blood_mist",1]],"adaptiveCoreMin":{"beowulf":1,"ragnar_lodbrok":1,"berserker":2,"berserker_de_oso":2,"ulfhednar":2},"adaptiveMaxSwaps":10,"aiLevel":57,"aiDrawBonus":9,"aiHonorBonus":23,"aiStyle":"Tier 5 · Mapa 19 · axe adaptativo de alta dificultad","desc":"Derrota a Beowulf y abre el acceso final.","rewardCard":"beowulf"}]};

const ADVENTURE_CHAPTER_20_1={"id":"chapter20_1","number":"20.1","levelRange":"58–60","mapBackground":"assets/story/map_hallvalla_chapter_3_1.webp","title":"El último juramento","desc":"La persecución termina en la cámara bajo HallValla. Satanyahu intenta reescribir el Primer Juramento usando el eco de las siete llaves y tu linaje como la última condición que aún no puede falsificar.","introTitle":"20.1 El último juramento","introText":"La cámara final no contiene un tesoro. Contiene una estructura capaz de convertir un juramento en ley sobre toda HallValla. Satanyahu lleva décadas intentando cambiar una sola cláusula: sustituir a los siete custodios por una única voluntad. Tu padre llegó hasta aquí, comprendió el precio y cerró la cámara desde dentro para impedirlo. Terral murió para evitar que Satanyahu te trajera hasta la misma decisión. Ahora estás aquí de todos modos, pero ya no eres la persona a la que Satanyahu empezó a conducir.","requiresChapter":"chapter19_1","packType":"improved_magic_trap","battles":[{"id":"chapter20_1_battle1","num":1,"title":"Los siete portadores falsos","enemyName":"Guerrero del Juramento Copiado","enemyLeaderType":"warrior","image":"assets/story/adventure_1_1/1_1_5_el_usurpador.webp","enemyIntro":"Siete campeones sostienen copias imperfectas de las marcas. Satanyahu necesita que parezcan suficientes para que la cámara acepte el reemplazo.","xp":2540,"gold":722,"cardPack":true,"packType":"improved_magic_trap","enemyLegendaryCards":["julius_caesar","hector_troy","leonidas","richard_lionheart","alexander_magnus"],"adaptiveFixedDeck":[["julius_caesar",1],["hector_troy",1],["leonidas",1],["richard_lionheart",1],["alexander_magnus",1],["roman_legionary",3],["greek_hoplite",3],["guardian",3],["armored_man_at_arms",3],["samurai_katana",3],["spearman",3],["dust_guard_plus",2],["shield_wall",2],["heal",2],["pharaoh_blessing_plus",1]],"adaptiveCoreMin":{"julius_caesar":1,"hector_troy":1,"roman_legionary":2,"greek_hoplite":2,"guardian":2},"adaptiveMaxSwaps":10,"aiLevel":58,"aiDrawBonus":8,"aiHonorBonus":23,"aiStyle":"Tier 5 · Mapa 20 · warrior adaptativo de alta dificultad","desc":"Destruye los portadores falsos antes de que el nuevo juramento pueda comenzar."},{"id":"chapter20_1_battle2","num":2,"title":"La voz de Terral","enemyName":"Arquera de la Memoria Robada","enemyLeaderType":"archer","image":"assets/story/adventure_2_1/2_1_3_el_blanco_de_invierno.webp","enemyIntro":"La cámara reproduce la voz de Terral ordenándote avanzar por una ruta concreta. La frase es perfecta salvo por una palabra que él nunca habría usado.","xp":2575,"gold":731,"cardPack":true,"packType":"improved_magic_trap","enemyLegendaryCards":["arjuna","simo_hayha","nasu_no_yoichi"],"adaptiveFixedDeck":[["arjuna",1],["simo_hayha",1],["nasu_no_yoichi",1],["archer",3],["egyptian_line_archer",3],["new_kingdom_archer",3],["roman_auxiliary_sagittarius",3],["samurai_yabusame",3],["scythian_horse_archer",3],["fireball",2],["poison_spell",2],["paralysis_spell",2],["skirmisher_cloak",1],["retreat_strap",1],["warning_rune_plus",1]],"adaptiveCoreMin":{"arjuna":1,"simo_hayha":1,"archer":2,"new_kingdom_archer":2,"roman_auxiliary_sagittarius":2},"adaptiveMaxSwaps":10,"aiLevel":58,"aiDrawBonus":8,"aiHonorBonus":23,"aiStyle":"Tier 5 · Mapa 20 · archer adaptativo de alta dificultad","desc":"Rompe la memoria fabricada y conserva la última decisión como tuya."},{"id":"chapter20_1_battle3","num":3,"title":"El padre sin rostro","enemyName":"Sombra del Padre","enemyLeaderType":"assassin","image":"assets/story/adventure_3_1/3_1_3_el_maestro_sin_espada.webp","enemyIntro":"Satanyahu reconstruye la silueta de tu padre con recuerdos incompletos. La figura intenta convencerte de entregar voluntariamente la sangre que falta.","xp":2610,"gold":740,"cardPack":true,"packType":"improved_magic_trap","enemyLegendaryCards":["fuma_kotaro","hattori_hanzo","miyamoto_musashi"],"adaptiveFixedDeck":[["fuma_kotaro",1],["hattori_hanzo",1],["miyamoto_musashi",1],["geisha_encubierta",3],["scout",3],["saboteador_iga",3],["samurai_katana",3],["ulfhednar",3],["shadow_cut",2],["false_crown",2],["broken_blood_oath",2],["poison_spell",2],["paralysis_spell",2],["smoke_bomb",2]],"adaptiveCoreMin":{"fuma_kotaro":1,"hattori_hanzo":1,"geisha_encubierta":2,"scout":2,"saboteador_iga":2},"adaptiveMaxSwaps":10,"aiLevel":59,"aiDrawBonus":8,"aiHonorBonus":24,"aiStyle":"Tier 5 · Mapa 20 · assassin adaptativo de alta dificultad","desc":"Destruye la imitación sin destruir lo que recuerdas de tu padre."},{"id":"chapter20_1_battle4","num":4,"title":"El sabueso encadenado","enemyName":"Cú Chulainn","enemyLeaderType":"axe","image":"assets/story/adventure_4_1/4_1_4_el_estratega_errante.webp","enemyIntro":"Cú Chulainn está atado a la cámara por una versión anterior del juramento. Satanyahu lo obliga a defender el mecanismo. Vencerlo rompe la cláusula que lo mantiene encadenado y elimina la última protección entre tú y el ritual.","xp":2645,"gold":749,"cardPack":false,"packType":"improved_magic_trap","enemyLegendaryCards":["cu_chulainn","beowulf","ragnar_lodbrok","lu_bu","spartacus"],"adaptiveFixedDeck":[["cu_chulainn",1],["beowulf",1],["ragnar_lodbrok",1],["lu_bu",1],["spartacus",1],["berserker",3],["berserker_de_oso",3],["ulfhednar",3],["huscarl_anglosajon_hacha",3],["guardia_varega_hacha",3],["tanned_hide_harness",2],["rupture_bracers",2],["war_visor",2],["heal",2],["dust_guard_plus",1],["blood_mist",1]],"adaptiveCoreMin":{"cu_chulainn":1,"beowulf":1,"berserker":2,"berserker_de_oso":2,"ulfhednar":2},"adaptiveMaxSwaps":10,"aiLevel":59,"aiDrawBonus":8,"aiHonorBonus":24,"aiStyle":"Tier 5 · Mapa 20 · axe adaptativo de alta dificultad","desc":"Libera a Cú Chulainn y llega hasta Satanyahu.","rewardCard":"cu_chulainn"},{"id":"chapter20_1_battle5","num":5,"title":"Satanyahu","enemyName":"Satanyahu","enemyLeaderType":"mage","image":"assets/story/adventure_6_1/6_1_5_la_corona_de_ceniza.webp","enemyIntro":"Satanyahu espera dentro del círculo central con el eco de las siete llaves alrededor. No intenta negar nada. Confiesa que necesitaba tu regreso, tu rabia, tus victorias y finalmente tu decisión de reunir las llaves. Creyó que conocerte significaba poder predecirte. El juramento exige sangre, memoria y consentimiento. Tiene las dos primeras condiciones al alcance, pero la tercera no puede ser falsificada. La batalla final no decide quién posee las llaves. Decide quién tiene derecho a escribir la última cláusula. Cuando Satanyahu cae, el eco se rompe y las siete llaves dejan de responder a una sola voluntad.","xp":3000,"gold":1000,"cardPack":true,"packType":"improved_magic_trap","enemyLegendaryCards":["king_solomon","merlin","morgana","ericto"],"adaptiveFixedDeck":[["king_solomon",1],["merlin",1],["morgana",1],["ericto",1],["arcane_adept",3],["acolyte_healer",3],["saboteador_iga",3],["guardian",3],["samurai_katana",3],["fireball",3],["sand_curse_plus",2],["poison_spell",2],["paralysis_spell",2],["heal",1],["stabilizing_focus",1]],"adaptiveCoreMin":{"king_solomon":1,"merlin":1,"arcane_adept":2,"acolyte_healer":2,"saboteador_iga":2},"adaptiveMaxSwaps":10,"aiLevel":60,"aiDrawBonus":9,"aiHonorBonus":24,"aiStyle":"Tier 5 · Mapa 20 · mage adaptativo de alta dificultad","desc":"Derrota a Satanyahu y conserva el Primer Juramento sin entregar tu voluntad.","rewardPackType":"improved_magic_trap"}]};
